import{_ as e,C as i,o as s,c as t,a4 as l,E as o}from"./chunks/framework.BNWYI55R.js";const b=JSON.parse('{"title":"四层评测方法论：从官方资格到体验稳定性的科学测评模型","description":"aijichang.blog 评测标准与方法论。详解官方资格、网络可达、任务执行与体验稳定性四层递进评测体系。","frontmatter":{"title":"四层评测方法论：从官方资格到体验稳定性的科学测评模型","description":"aijichang.blog 评测标准与方法论。详解官方资格、网络可达、任务执行与体验稳定性四层递进评测体系。","h1":"四层评测方法论：从官方资格到体验稳定性的科学测评模型","pageType":"article","canonicalPath":"/methodology/","primaryIntent":"方法论：公开本站评测四层递进模型、实验设计与数据脱敏规则","verifiedAt":"2026-10-21T00:00:00.000Z","modifiedAt":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"methodology/index.md","filePath":"methodology/index.md","lastUpdated":1792563027000}'),r={name:"methodology/index.md"};function p(c,a,d,h,u,g){const n=i("RelatedLinks");return s(),t("div",null,[a[0]||(a[0]=l(`<h1 id="四层评测方法论-从官方资格到体验稳定性的科学测评模型" tabindex="-1">四层评测方法论：从官方资格到体验稳定性的科学测评模型 <a class="header-anchor" href="#四层评测方法论-从官方资格到体验稳定性的科学测评模型" aria-label="Permalink to &quot;四层评测方法论：从官方资格到体验稳定性的科学测评模型&quot;">​</a></h1><p>在网络评测中，“能不能用”是一个高度模糊的口语化概念。很多用户在购买了某家标榜“全解锁”的机场后，依然频繁遭遇 403 阻断或无法观看 4K，其根本原因在于测评者把不同层级的技术边界混为一谈。</p><p>为了建立严谨、可量化、可重复复现的评测标准，本站实验室确立了<strong>四层递进评测方法论模型（Four-Layer Evaluation Framework）</strong>：</p><hr><h2 id="四层递进评测模型解析" tabindex="-1">四层递进评测模型解析 <a class="header-anchor" href="#四层递进评测模型解析" aria-label="Permalink to &quot;四层递进评测模型解析&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 第四层：体验稳定性 (Stability &amp; Experience)            │</span></span>
<span class="line"><span>│ 晚高峰抗压、RTT时延抖动、长文本长连接持续保活、无断流      │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 第三层：具体任务执行 (Task Execution)                  │</span></span>
<span class="line"><span>│ 账号登录跳转、500字流式文本生成、4K非自制剧播放、图片上传  │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 第二层：网络可达性与出口 (Network Reachability &amp; IP)   │</span></span>
<span class="line"><span>│ IP合法属地判定、非机房黑名单、TCP握手、TLS安全会话协商    │</span></span>
<span class="line"><span>├────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 第一层：官方服务资格 (Platform Eligibility)            │</span></span>
<span class="line"><span>│ 平台支持地区白名单、账户合规要求、客户端运行环境资质      │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="第一层-官方服务资格-platform-eligibility" tabindex="-1">第一层：官方服务资格（Platform Eligibility） <a class="header-anchor" href="#第一层-官方服务资格-platform-eligibility" aria-label="Permalink to &quot;第一层：官方服务资格（Platform Eligibility）&quot;">​</a></h3><ul><li><strong>判定标准</strong>：目标海外平台是否在该节点所在地区提供官方服务；</li><li><strong>典型案例</strong>：OpenAI 官方目前不向中国香港、俄罗斯、伊朗等地区开放服务。因此，无论香港节点的专线速度有多快、延迟有多低，它在第一层就已被判定为“不符合资格”。如果用户试图用纯正香港原生 IP 访问，直接会被阻断在门外。</li></ul><h3 id="第二层-网络可达性与出口-network-reachability-ip" tabindex="-1">第二层：网络可达性与出口（Network Reachability &amp; IP） <a class="header-anchor" href="#第二层-网络可达性与出口-network-reachability-ip" aria-label="Permalink to &quot;第二层：网络可达性与出口（Network Reachability &amp; IP）&quot;">​</a></h3><ul><li><strong>判定标准</strong>：客户端与目标平台的海外服务器之间能否顺利完成 TCP 三次握手与 TLS 证书协商，且节点的出口 IP 未被海外安全防火墙直接拉黑；</li><li><strong>典型案例</strong>：部分机场使用廉价机房 VPS，其 IP 在 Cloudflare 威胁库中的欺诈分（Fraud Score）高达 80 分。虽然物理网络通畅，但在握手阶段就会收到 403 Forbidden。</li></ul><h3 id="第三层-具体任务执行-task-execution" tabindex="-1">第三层：具体任务执行（Task Execution） <a class="header-anchor" href="#第三层-具体任务执行-task-execution" aria-label="Permalink to &quot;第三层：具体任务执行（Task Execution）&quot;">​</a></h3><ul><li><strong>判定标准</strong>：不仅要能打开首页，更要能够真实完整地跑通特定的业务用例；</li><li><strong>典型案例</strong>： <ul><li>在 ChatGPT 界面发送包含代码重构的长提示词，必须能够持续接收完整 SSE 数据流，中途不发生断流报错；</li><li>在 Netflix 上播放非自制独家版权片目，必须能够连续播放 180 秒以上无代理弹窗。</li></ul></li></ul><h3 id="第四层-体验稳定性-stability-experience" tabindex="-1">第四层：体验稳定性（Stability &amp; Experience） <a class="header-anchor" href="#第四层-体验稳定性-stability-experience" aria-label="Permalink to &quot;第四层：体验稳定性（Stability &amp; Experience）&quot;">​</a></h3><ul><li><strong>判定标准</strong>：在全网流量最高的晚高峰（20:00~22:30）拥塞期，指标能否保持恒定；</li><li><strong>核心量化参数</strong>： <ul><li><strong>RTT 往返时延极差</strong>：波动需小于 10ms；</li><li><strong>最后一跳丢包率</strong>：必须保持在 0.5% 以下；</li><li><strong>长连接保活时长</strong>：静默挂起 120 秒不发生 RST 断开。</li></ul></li></ul><hr><h2 id="严格的双基线实验环境" tabindex="-1">严格的双基线实验环境 <a class="header-anchor" href="#严格的双基线实验环境" aria-label="Permalink to &quot;严格的双基线实验环境&quot;">​</a></h2><p>所有参评数据均采集自两套标准化的物理网络接入环境：</p><ul><li><strong>主基线</strong>：华东千兆电信家庭光纤宽带（标准双栈公网 IPv4/IPv6，路由直连）；</li><li><strong>副基线</strong>：北方联通 5G 移动蜂窝热点（典型商旅与蜂窝移动网络环境）。</li></ul><p>杜绝在机房云服务器对测、或使用企业高阶精品网对普通家庭宽带进行不公正对比。</p>`,19)),o(n,{links:[{title:"解锁实测实验中心 (/tests/)",desc:"查阅基于本方法论产生的最新抓包批次与观测数据",url:"/tests/"},{title:"AI机场专项选型 (/ai/)",desc:"查看 ChatGPT、Claude 与 Gemini 的四层任务实测表现",url:"/ai/"},{title:"流媒体机场选型指南 (/streaming/)",desc:"核验 Netflix、Disney+ 与 YouTube 4K 的真实播放保障",url:"/streaming/"}]})])}const P=e(r,[["render",p]]);export{b as __pageData,P as default};
